 out=dict(identity=identity,counts=counts,all_risks_rolled_back=True,prepublished_bootstrap_root_retained=True,caller_xid=xid,caller_xact_status=status,c_verifier_acls=acls,model_issuer_direct_c_execute=False,current_frozen_source_hashes=hashes,current_frozen_helper_hashes=helpers,combined_proof_sha256=hashlib.sha256((N/'combined-preparation.json').read_bytes()).hexdigest(),actual_target_result_present=False,formal_root_provenance_verified=False,full_task_delivered=False,execution_allowed=False)
